syntax:
template< class InputIt, class OutputIt >
OutputIt std::copy(InputIt first, InputIt last, OutputIt d_first);
// Implementation notes: 'first' and 'last' are input iterators for the source range; 'd_first' is an output iterator for the destination. The compiler deduces types at compile-time via templates, and for output iterators like std::ostream_iterator<T>(out, delim), each *d_first++ = value; internally calls out << value << delim;, which is not random access and may prevent certain optimizations.
